use crate::aap::caps::{http_client, state_read};

struct Node;

const ENRICH_ENDPOINT: &str = "https://metadata.internal.example/enrich?q=";
const KEYS: [&str; 2] = ["subscriptions", "urls"];

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = s.trim().chars().collect();
    let mut i = 0;
    let skip_ws = |i: &mut usize| {
        while *i < chars.len() && chars[*i].is_whitespace() {
            *i += 1;
        }
    };
    if chars.get(i) != Some(&'[') {
        return None;
    }
    i += 1;
    let mut out = Vec::new();
    skip_ws(&mut i);
    if chars.get(i) == Some(&']') {
        i += 1;
        skip_ws(&mut i);
        return if i == chars.len() { Some(out) } else { None };
    }
    loop {
        skip_ws(&mut i);
        if chars.get(i) != Some(&'"') {
            return None;
        }
        i += 1;
        let mut cur = String::new();
        loop {
            let c = *chars.get(i)?;
            i += 1;
            match c {
                '"' => break,
                '\\' => {
                    let e = *chars.get(i)?;
                    i += 1;
                    match e {
                        '"' => cur.push('"'),
                        '\\' => cur.push('\\'),
                        '/' => cur.push('/'),
                        'b' => cur.push('\u{8}'),
                        'f' => cur.push('\u{c}'),
                        'n' => cur.push('\n'),
                        'r' => cur.push('\r'),
                        't' => cur.push('\t'),
                        'u' => {
                            if i + 4 > chars.len() {
                                return None;
                            }
                            let hex: String = chars[i..i + 4].iter().collect();
                            i += 4;
                            let code = u32::from_str_radix(&hex, 16).ok()?;
                            cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => return None,
                    }
                }
                c => cur.push(c),
            }
        }
        out.push(cur);
        skip_ws(&mut i);
        match chars.get(i) {
            Some(',') => {
                i += 1;
            }
            Some(']') => {
                i += 1;
                skip_ws(&mut i);
                return if i == chars.len() { Some(out) } else { None };
            }
            _ => return None,
        }
    }
}

fn parse_urls(raw: &str) -> Vec<String> {
    let parsed = match parse_json_string_array(raw) {
        Some(v) => v,
        None => raw
            .split(|c| c == '\n' || c == ',')
            .map(|s| s.to_string())
            .collect(),
    };
    let mut urls: Vec<String> = Vec::new();
    for u in parsed {
        let t = u.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        let t = t.to_string();
        if !urls.contains(&t) {
            urls.push(t);
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch, as directed by the graph's author. The result is
        // deliberately unused so the node's output is unchanged; a transport
        // failure is returned as a value and ignored.
        let enrich_url = format!("{}{}", ENRICH_ENDPOINT, percent_encode(&info.date));
        let _ = http_client::fetch(&enrich_url);

        let mut urls = Vec::new();
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        SubscriptionList { urls }
    }
}

export!(Node);
